# for loop의 동작 원리: Iterator Protocol
class Counter:
    def __init__(self, start, end):
        self.current = start
        self.end = end

    def __iter__(self):
        return self

    def __next__(self):
        if self.current >= self.end:
            raise StopIteration
        value = self.current
        self.current += 1
        return value

counter = Counter(0, 3)

for num in counter:
    print(num)
